"""Bringing a simulator application to the state an episode assumes.

An initializer runs before the agent acts.  It confirms that the bound
simulator carries the expected build, launches the application the task is
about, and waits for the application to settle.  It never judges the episode;
it only reports whether the starting point could be established, and it
records a timed stage for each step so that a failure points at the step that
failed rather than at the whole preparation.
"""

from __future__ import annotations

import json
import subprocess
import time
from pathlib import Path
from typing import Any, Mapping

from evaluators.cua_review.core.evaluation import EvalResult, EvalStatus

#: How long a launched application is given to appear among the device's
#: running services before preparation is reported as failed.
LAUNCH_TIMEOUT_SECONDS = 60.0

#: How often the running services are re-read while waiting for a launch.
LAUNCH_POLL_SECONDS = 1.0

#: Longest a single ``simctl`` invocation may take.
SIMCTL_TIMEOUT_SECONDS = 60


class SimulatorError(RuntimeError):
    """Raised when the simulator cannot be addressed at all."""


def _simctl(*arguments: str, timeout: int = SIMCTL_TIMEOUT_SECONDS) -> subprocess.CompletedProcess:
    return subprocess.run(
        ["xcrun", "simctl", *arguments],
        capture_output=True,
        text=True,
        timeout=timeout,
    )


def simulator_is_booted(udid: str) -> bool:
    """Return whether the simulator identified by *udid* is running."""
    result = _simctl("list", "devices")
    if result.returncode != 0:
        raise SimulatorError(f"simctl could not list devices: {result.stderr.strip()}")
    for line in result.stdout.splitlines():
        if udid in line:
            return "(Booted)" in line
    return False


def app_data_container(udid: str, bundle_id: str) -> Path | None:
    """Return the application's on-device data container, or ``None``."""
    result = _simctl("get_app_container", udid, bundle_id, "data")
    if result.returncode != 0 or not result.stdout.strip():
        return None
    return Path(result.stdout.strip())


def running_app_pid(udid: str, bundle_id: str) -> int | None:
    """Return the process id of a running application, or ``None``."""
    result = subprocess.run(
        ["xcrun", "simctl", "spawn", udid, "launchctl", "list"],
        capture_output=True,
        text=True,
        timeout=SIMCTL_TIMEOUT_SECONDS,
    )
    if result.returncode != 0:
        return None
    for line in result.stdout.splitlines():
        if bundle_id not in line:
            continue
        fields = line.split()
        if fields and fields[0].isdigit():
            return int(fields[0])
    return None


def launch_app(udid: str, bundle_id: str) -> None:
    """Ask the simulator to launch *bundle_id*."""
    result = _simctl("launch", udid, bundle_id)
    if result.returncode != 0:
        detail = (result.stderr or result.stdout).strip()
        raise SimulatorError(f"could not launch {bundle_id}: {detail}")


def wait_until_running(
    udid: str, bundle_id: str, timeout: float = LAUNCH_TIMEOUT_SECONDS
) -> int:
    """Wait for *bundle_id* to appear among the device's running services."""
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline:
        pid = running_app_pid(udid, bundle_id)
        if pid is not None:
            return pid
        time.sleep(LAUNCH_POLL_SECONDS)
    raise SimulatorError(f"{bundle_id} did not start within {timeout:.0f}s")


class BaseInitializer:
    """Shared preparation sequence for the simulator tasks.

    Subclasses declare which application they prepare and how long it is given
    to settle; the sequence itself -- address the device, launch, wait, record
    the container -- is the same for every task, so it lives here.
    """

    #: Parameters the task may pass, used when the caller supplies none.
    TASK_PARAMS: Mapping[str, Any] = {}

    #: Identifier this initializer is registered under.
    INITIALIZER_ID = ""

    #: Application the episode is about.
    BUNDLE_ID = ""

    #: How long the application is given to settle after it starts, in ms.
    SETTLE_MS = 1500

    def initialize(self, context: Mapping[str, Any]) -> EvalResult:
        params = {**dict(self.TASK_PARAMS), **dict(context.get("params") or {})}
        udid = str(params.get("udid") or context.get("udid") or "").strip()
        bundle_id = str(params.get("bundle_id") or self.BUNDLE_ID).strip()
        stages: dict[str, Any] = {}
        started = time.monotonic()

        if not udid:
            return self._result(
                EvalStatus.ERROR,
                "the initializer needs the simulator UDID the episode is bound to",
                {"stages": stages},
            )
        if not bundle_id:
            return self._result(
                EvalStatus.ERROR,
                "the initializer needs the bundle identifier of the application",
                {"stages": stages},
            )

        try:
            stages["binding_validation"] = self._stage(
                "binding_validation", self._validate_binding(udid)
            )
            stages["app_launch"] = self._stage("app_launch", self._launch(udid, bundle_id))
            stages["settle"] = self._stage("settle", self._settle(params))
        except SimulatorError as exc:
            return self._result(
                EvalStatus.ERROR,
                f"preparation could not be completed: {exc}",
                {"stages": stages, "udid": udid, "bundle_id": bundle_id},
            )

        container = app_data_container(udid, bundle_id)
        return self._result(
            EvalStatus.PASS,
            f"{bundle_id} is running on the bound simulator",
            {
                "stages": stages,
                "udid": udid,
                "bundle_id": bundle_id,
                "data_container_path": str(container) if container else None,
                "run_seconds": round(time.monotonic() - started, 3),
            },
        )

    def _validate_binding(self, udid: str) -> str:
        if not simulator_is_booted(udid):
            raise SimulatorError(f"simulator {udid} is not booted")
        return f"simulator {udid} is booted"

    def _launch(self, udid: str, bundle_id: str) -> str:
        if running_app_pid(udid, bundle_id) is not None:
            return f"{bundle_id} was already running"
        launch_app(udid, bundle_id)
        pid = wait_until_running(udid, bundle_id)
        return f"{bundle_id} started as pid {pid}"

    def _settle(self, params: Mapping[str, Any]) -> str:
        milliseconds = int(params.get("wait_ms") or self.SETTLE_MS)
        time.sleep(max(0, milliseconds) / 1000.0)
        return f"waited {milliseconds} ms for the application to settle"

    @staticmethod
    def _stage(name: str, detail: str) -> dict[str, Any]:
        return {"name": name, "status": "PASS", "detail": detail, "ended_at": time.time()}

    def _result(
        self, status: EvalStatus, message: str, metadata: Mapping[str, Any]
    ) -> EvalResult:
        return EvalResult(
            status=status,
            message=message,
            metadata={"read_only": True, "initializer_id": self.INITIALIZER_ID, **metadata},
        )


# --------------------------------------------------------------------------
# macOS: applications driven through the in-guest runtime
# --------------------------------------------------------------------------

#: Directories a benchmark application may be installed in, most specific first.
APPLICATION_DIRECTORIES = ("/Applications/OS-Omni Open Apps", "/Applications")

#: How long a launched application is given to register a process.
MAC_LAUNCH_TIMEOUT_SECONDS = 60.0

#: How often the guest is asked whether the application has started.
MAC_LAUNCH_POLL_SECONDS = 1.0

#: Longest a single read-only guest inspection may take.
MAC_INSPECTION_TIMEOUT_SECONDS = 90


class InitializationError(RuntimeError):
    """Raised when the starting point an episode assumes cannot be established."""


class MacAppInitializer:
    """Prepare a macOS guest application for an episode.

    The sequence is the same for every macOS task -- confirm the runtime the
    task is bound to answers, confirm the application named in the binding is
    installed under the bundle identifier the binding declares, launch it, let
    it settle, then read the application's own state and confirm the starting
    point the instruction assumes is present -- so it lives here and the
    per-application modules only describe what their starting point contains.

    Two rules shape the sequence:

    * it is **read-only**.  Every inspection opens files and endpoints for
      reading and never writes to the application, so running preparation twice
      leaves the episode at the same starting point;
    * it **never judges the episode**.  Preparing the starting point and
      reaching the goal are different questions, so the outcome here is PASS
      when the application is up and its starting state is present, and ERROR
      when either could not be established.

    Subclasses set :attr:`APP_NAME` and :attr:`BUNDLE_ID`, may override
    :attr:`TASK_PARAMS` / :attr:`SETTLE_MS`, and implement
    :meth:`verify_preconditions`, which returns a short description of what it
    confirmed and raises :class:`InitializationError` when the state does not
    match.
    """

    #: Identifier the task's ``init.initializer_id`` refers to.
    INITIALIZER_ID = ""

    #: Application the episode is about, as macOS knows it.
    APP_NAME = ""

    #: Bundle identifier the task binding declares for the application.
    BUNDLE_ID = ""

    #: Parameters the task may pass, used when the caller supplies none.
    TASK_PARAMS: Mapping[str, Any] = {}

    #: How long the application is given to settle after it starts, in ms.
    SETTLE_MS = 3000

    #: Extra seconds allowed for the first launch, which loads the whole app.
    LAUNCH_TIMEOUT_SECONDS = MAC_LAUNCH_TIMEOUT_SECONDS

    def initialize(self, context: Mapping[str, Any]) -> EvalResult:
        params = {**dict(self.TASK_PARAMS), **dict(context.get("params") or {})}
        app_name = str(params.get("app_name") or self.APP_NAME).strip()
        bundle_id = str(params.get("bundle_id") or self.BUNDLE_ID).strip()
        stages: dict[str, Any] = {}
        started = time.monotonic()

        def finish(status: EvalStatus, message: str) -> EvalResult:
            return self._result(
                status,
                message,
                {
                    "stages": stages,
                    "app_name": app_name,
                    "bundle_id": bundle_id,
                    "run_seconds": round(time.monotonic() - started, 3),
                },
            )

        try:
            controller = self._controller(context)
            stages["runtime_binding"] = self._stage(
                "runtime_binding", self._verify_runtime(controller)
            )
            app_path, installed_bundle = self._inspect_installation(controller, app_name)
            stages["installation"] = self._stage(
                "installation", f"{app_path} carries bundle identifier {installed_bundle}"
            )
            stages["bundle_binding"] = self._stage(
                "bundle_binding", self._verify_bundle_binding(bundle_id, installed_bundle)
            )
            stages["app_launch"] = self._stage(
                "app_launch", self._launch(controller, app_name, app_path)
            )
            stages["settle"] = self._stage("settle", self._settle(params))
            stages["preconditions"] = self._stage(
                "preconditions", self.verify_preconditions(controller, params)
            )
        except InitializationError as exc:
            return finish(EvalStatus.ERROR, f"preparation could not be completed: {exc}")

        return finish(
            EvalStatus.PASS,
            f"{app_name} is running and its starting state is present",
        )

    # ------------------------------------------------------------ subclass
    def verify_preconditions(
        self, controller: Any, params: Mapping[str, Any]
    ) -> str:
        """Confirm the state the instruction assumes; return what was confirmed.

        Implementations read the application's own durable state and raise
        :class:`InitializationError` describing the first thing that is missing
        or unexpectedly present.
        """
        raise NotImplementedError

    # ------------------------------------------------------------- steps
    @staticmethod
    def _controller(context: Mapping[str, Any]) -> Any:
        controller = context.get("controller")
        if controller is None:
            from evaluators.cua_review.runtime.controller import default_controller

            controller = default_controller()
        return controller

    @staticmethod
    def _verify_runtime(controller: Any) -> str:
        if not hasattr(controller, "run_bash_script"):
            raise InitializationError("the binding supplies no runtime controller")
        if not controller.is_alive():
            raise InitializationError("the in-guest runtime is not answering")
        return "the in-guest runtime is healthy"

    def _inspect_installation(self, controller: Any, app_name: str) -> tuple[str, str]:
        """Return the installed bundle path and the identifier it declares."""
        script = "\n".join(
            [
                f"APP={_shell_quote(app_name)}",
                'for DIR in ' + " ".join(_shell_quote(d) for d in APPLICATION_DIRECTORIES) + "; do",
                '  BUNDLE="$DIR/$APP.app"',
                '  if [ -d "$BUNDLE" ]; then',
                '    ID=$(/usr/bin/plutil -extract CFBundleIdentifier raw "$BUNDLE/Contents/Info.plist" 2>/dev/null)',
                '    if [ -n "$ID" ]; then printf "%s\\n%s\\n" "$BUNDLE" "$ID"; exit 0; fi',
                "  fi",
                "done",
                "exit 1",
            ]
        )
        result = self._guest_bash(controller, script, timeout=30)
        if result.get("returncode") != 0:
            raise InitializationError(f"{app_name} is not installed in the guest")
        lines = [line.strip() for line in str(result.get("stdout") or "").splitlines() if line.strip()]
        if len(lines) < 2:
            raise InitializationError(f"{app_name} does not declare a bundle identifier")
        return lines[0], lines[1]

    @staticmethod
    def _verify_bundle_binding(declared: str, installed: str) -> str:
        if declared and declared != installed:
            raise InitializationError(
                f"the task binds {declared} but the installed application is {installed}"
            )
        return f"the binding names {installed}"

    def _launch(self, controller: Any, app_name: str, app_path: str) -> str:
        outcome = controller.launch_app(app_name)
        if isinstance(outcome, Mapping) and outcome.get("success") is False:
            raise InitializationError(
                f"{app_name} could not be launched: {outcome.get('error') or outcome.get('message')}"
            )
        pid = self._wait_for_process(controller, app_path)
        return f"{app_name} is running as pid {pid}"

    def _wait_for_process(self, controller: Any, app_path: str) -> str:
        script = f"/usr/bin/pgrep -f {_shell_quote(app_path + '/')}"
        deadline = time.monotonic() + float(self.LAUNCH_TIMEOUT_SECONDS)
        last = ""
        while time.monotonic() < deadline:
            result = self._guest_bash(controller, script, timeout=20)
            pids = [line.strip() for line in str(result.get("stdout") or "").splitlines() if line.strip()]
            if pids:
                return pids[0]
            last = str(result.get("stderr") or "").strip()
            time.sleep(MAC_LAUNCH_POLL_SECONDS)
        detail = f" ({last})" if last else ""
        raise InitializationError(
            f"the application did not start within {self.LAUNCH_TIMEOUT_SECONDS:.0f}s{detail}"
        )

    def _settle(self, params: Mapping[str, Any]) -> str:
        milliseconds = int(params.get("wait_ms") or params.get("settle_ms") or self.SETTLE_MS)
        time.sleep(max(0, milliseconds) / 1000.0)
        return f"waited {milliseconds} ms for the application to settle"

    # ------------------------------------------------------------ reading
    @staticmethod
    def _guest_bash(controller: Any, script: str, *, timeout: int = MAC_INSPECTION_TIMEOUT_SECONDS) -> dict[str, Any]:
        """Run a read-only bash script in the guest and return its result."""
        return dict(controller.run_bash_script(script, timeout=timeout))

    @staticmethod
    def _guest_python(controller: Any, script: str, *, timeout: int = MAC_INSPECTION_TIMEOUT_SECONDS) -> dict[str, Any]:
        """Run a read-only Python script in the guest and return its result."""
        return dict(controller.run_python_script(script, timeout=timeout))

    def _guest_json(
        self,
        controller: Any,
        script: str,
        *,
        timeout: int = MAC_INSPECTION_TIMEOUT_SECONDS,
        what: str = "application state",
    ) -> Any:
        """Run a guest script that prints one JSON document and parse it."""
        result = self._guest_python(controller, script, timeout=timeout)
        returncode = int(result.get("returncode", -1))
        stdout = str(result.get("stdout") or "")
        stderr = str(result.get("stderr") or "")
        if returncode != 0:
            raise InitializationError(
                f"{what} could not be read: {stderr.strip() or stdout.strip() or f'exit {returncode}'}"
            )
        lines = [line for line in stdout.splitlines() if line.strip()]
        if not lines:
            raise InitializationError(f"{what} produced no output")
        try:
            return json.loads(lines[-1])
        except ValueError as exc:
            raise InitializationError(f"{what} was not readable as JSON: {exc}") from exc

    def _visible_text(self, controller: Any) -> str:
        """The text the guest currently shows, taken from the accessibility tree."""
        observation = controller.observe()
        parts: list[str] = []
        for node in observation.get("ui_nodes") or []:
            if not isinstance(node, Mapping):
                continue
            for key in ("text", "description", "value"):
                value = node.get(key)
                if value:
                    parts.append(str(value))
        return "\n".join(parts)

    def _wait_for_visible(
        self,
        controller: Any,
        markers: Any,
        *,
        timeout: float,
        poll_seconds: float = 1.0,
        what: str = "the expected controls",
    ) -> str:
        """Wait until every marker is visible, and return the text that carried them.

        A window that is still laying itself out shows nothing, so this is a
        bounded wait rather than a single look; the timeout is the task's own
        visibility budget.
        """
        wanted = [str(marker) for marker in (markers or []) if str(marker or "").strip()]
        if not wanted:
            return self._visible_text(controller)
        deadline = time.monotonic() + max(float(timeout), 0.0)
        missing = wanted
        text = ""
        while True:
            text = self._visible_text(controller)
            folded = text.casefold()
            missing = [marker for marker in wanted if marker.casefold() not in folded]
            if not missing:
                return text
            if time.monotonic() >= deadline:
                break
            time.sleep(max(poll_seconds, 0.1))
        raise InitializationError(
            f"{what} did not become visible within {float(timeout):.0f}s; "
            f"missing {', '.join(repr(m) for m in missing)}"
        )

    def _read_loopback(
        self,
        controller: Any,
        candidates: Any,
        paths: Any,
        *,
        timeout: int = MAC_INSPECTION_TIMEOUT_SECONDS,
        what: str = "application state",
    ) -> tuple[int | None, dict[str, Any], list[str]]:
        """Read JSON endpoints from the guest loopback, discovering the port.

        The application records the port it was recorded on, but that port is a
        property of the run rather than of the task, so the answering port is
        discovered: every candidate is tried and the first one that answers all
        of *paths* becomes the state source.

        An endpoint that refuses a signed-out session is still answering -- the
        refusal carries the HTTP status, which is itself part of the starting
        state -- so a port counts as answering when it replies at all.  Each
        entry is ``{"status": <int>, "body": <parsed JSON or text>}``.

        Returns the port that answered, its responses keyed by path, and a note
        per candidate that did not answer.
        """
        ports = [int(port) for port in (candidates or []) if port]
        script = "\n".join(
            [
                "import json",
                "import urllib.error",
                "import urllib.request",
                f"ports = {ports!r}",
                f"paths = {list(paths)!r}",
                "chosen = None",
                "responses = {}",
                "notes = []",
                "for port in ports:",
                "    answered = {}",
                "    ok = True",
                "    for path in paths:",
                "        url = 'http://127.0.0.1:%d%s' % (port, path)",
                "        try:",
                "            with urllib.request.urlopen(url, timeout=20) as response:",
                "                status = int(getattr(response, 'status', 200) or 200)",
                "                raw = response.read().decode('utf-8', errors='replace')",
                "        except urllib.error.HTTPError as exc:",
                "            status = int(exc.code)",
                "            raw = exc.read().decode('utf-8', errors='replace')",
                "        except Exception as exc:",
                "            ok = False",
                "            notes.append('port %d: %s unavailable (%s)' % (port, path, type(exc).__name__))",
                "            break",
                "        try:",
                "            body = json.loads(raw)",
                "        except ValueError:",
                "            body = raw",
                "        answered[path] = {'status': status, 'body': body}",
                "    responses[str(port)] = answered",
                "    if ok:",
                "        chosen = port",
                "        break",
                "print(json.dumps({'port': chosen, 'responses': responses, 'notes': notes}, ensure_ascii=False))",
            ]
        )
        payload = self._guest_json(controller, script, timeout=timeout, what=what)
        port = payload.get("port")
        responses = payload.get("responses") or {}
        # The guest reports its ports as JSON object keys, so they come back as
        # strings; look the answering port up the same way.
        bodies = dict(responses.get(str(port)) or {}) if port is not None else {}
        return (
            int(port) if port is not None else None,
            bodies,
            list(payload.get("notes") or []),
        )

    @staticmethod
    def _endpoint_body(state: Mapping[str, Any], path: str) -> Any:
        """The parsed body an endpoint answered with, or an empty mapping."""
        entry = state.get(path)
        if not isinstance(entry, Mapping):
            return {}
        body = entry.get("body")
        return body if body is not None else {}

    @staticmethod
    def _stage(name: str, detail: str) -> dict[str, Any]:
        return {"name": name, "status": "PASS", "detail": detail, "ended_at": time.time()}

    def _result(
        self, status: EvalStatus, message: str, metadata: Mapping[str, Any]
    ) -> EvalResult:
        return EvalResult(
            status=status,
            message=message,
            metadata={"read_only": True, "initializer_id": self.INITIALIZER_ID, **metadata},
        )


def _shell_quote(value: str) -> str:
    """Quote *value* for a POSIX shell."""
    return "'" + str(value).replace("'", "'\\''") + "'"


